import Decimal from 'decimal.js';
import { documentCurrencyScale } from './totals';

// Amount in words is generated by the server so it always matches the numeric
// total. If a currency cannot be described safely, the numeric amount is shown
// instead of inventing broken English (docs/41 §10.7).

const ONES = [
  'zero',
  'one',
  'two',
  'three',
  'four',
  'five',
  'six',
  'seven',
  'eight',
  'nine',
  'ten',
  'eleven',
  'twelve',
  'thirteen',
  'fourteen',
  'fifteen',
  'sixteen',
  'seventeen',
  'eighteen',
  'nineteen',
];

const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];

const SCALES = [
  { value: 1_000_000_000_000_000n, singular: 'quadrillion', plural: 'quadrillion' },
  { value: 1_000_000_000_000n, singular: 'trillion', plural: 'trillion' },
  { value: 1_000_000_000n, singular: 'billion', plural: 'billion' },
  { value: 1_000_000n, singular: 'million', plural: 'million' },
  { value: 1_000n, singular: 'thousand', plural: 'thousand' },
] as const;

const CURRENCY_NAMES: Record<string, { major: string; minor: string }> = {
  USD: { major: 'US Dollars', minor: 'Cents' },
  EUR: { major: 'Euros', minor: 'Cents' },
  GBP: { major: 'Pounds Sterling', minor: 'Pence' },
  AUD: { major: 'Australian Dollars', minor: 'Cents' },
  CAD: { major: 'Canadian Dollars', minor: 'Cents' },
  CNY: { major: 'Chinese Yuan', minor: 'Fen' },
  JPY: { major: 'Japanese Yen', minor: '' },
  AED: { major: 'UAE Dirhams', minor: 'Fils' },
  SGD: { major: 'Singapore Dollars', minor: 'Cents' },
  HKD: { major: 'Hong Kong Dollars', minor: 'Cents' },
  KRW: { major: 'South Korean Won', minor: '' },
};

const CURRENCY_NAMES_ZH: Record<string, string> = {
  USD: '美元',
  EUR: '欧元',
  GBP: '英镑',
  AUD: '澳元',
  CAD: '加元',
  CNY: '人民币',
  JPY: '日元',
  AED: '迪拉姆',
  SGD: '新加坡元',
  HKD: '港元',
  KRW: '韩元',
};

function underThousand(value: number): string {
  if (value < 20) return ONES[value]!;
  if (value < 100) {
    const tens = Math.floor(value / 10);
    const remainder = value % 10;
    return remainder === 0 ? TENS[tens]! : `${TENS[tens]} ${ONES[remainder]}`;
  }
  const hundreds = Math.floor(value / 100);
  const remainder = value % 100;
  return remainder === 0
    ? `${ONES[hundreds]} hundred`
    : `${ONES[hundreds]} hundred ${underThousand(remainder)}`;
}

function integerToWords(value: bigint): string {
  if (value === 0n) return 'zero';
  const parts: string[] = [];
  let remaining = value;
  for (const scale of SCALES) {
    if (remaining >= scale.value) {
      const count = remaining / scale.value;
      remaining %= scale.value;
      const countWords = integerToWords(count);
      parts.push(`${countWords} ${count === 1n ? scale.singular : scale.plural}`);
    }
  }
  if (remaining > 0n) {
    parts.push(underThousand(Number(remaining)));
  }
  return parts.join(' ');
}

function capitalise(value: string): string {
  return value
    .split(' ')
    .map((word) => (word.length === 0 ? word : `${word.charAt(0).toUpperCase()}${word.slice(1)}`))
    .join(' ');
}

const ZH_DIGITS = ['零', '壹', '贰', '叁', '肆', '伍', '陆', '柒', '捌', '玖'];
const ZH_UNITS = ['', '拾', '佰', '仟'];
const ZH_BIG_UNITS = ['', '万', '亿', '兆'];

function toChineseInteger(value: bigint): string {
  if (value === 0n) return '零';
  const digits = value.toString();
  const groups: number[][] = [];
  for (let end = digits.length; end > 0; end -= 4) {
    const start = Math.max(0, end - 4);
    groups.unshift(
      digits
        .slice(start, end)
        .split('')
        .map((digit) => Number(digit)),
    );
  }
  let result = '';
  let pendingZero = false;
  groups.forEach((group, groupIndex) => {
    const bigIndex = groups.length - 1 - groupIndex;
    let groupText = '';
    group.forEach((digit, index) => {
      const unit = ZH_UNITS[group.length - 1 - index]!;
      if (digit === 0) {
        pendingZero = groupText.length > 0 || result.length > 0;
        return;
      }
      if (pendingZero) {
        groupText += '零';
        pendingZero = false;
      }
      groupText += `${ZH_DIGITS[digit]}${unit}`;
    });
    if (groupText.length > 0) {
      result += `${groupText}${ZH_BIG_UNITS[bigIndex]}`;
      pendingZero = false;
    } else if (result.length > 0 && bigIndex > 0) {
      pendingZero = true;
    }
  });
  return result.replace(/零+$/u, '') || '零';
}

/**
 * Returns an English (or Chinese) amount-in-words sentence.
 *
 * `zh-CN` output follows the financial uppercase style commonly used on
 * Chinese invoices. Unsupported currencies fall back to the numeric amount so
 * a wrong currency name is never printed.
 */
export function amountInWords(
  amount: string,
  currency: string,
  locale: 'en-US' | 'zh-CN' = 'en-US',
): string {
  const code = currency.toUpperCase();
  const scale = documentCurrencyScale(code);
  let value: Decimal;
  try {
    value = new Decimal(amount);
  } catch {
    return `${code} ${amount}`;
  }
  if (!value.isFinite() || value.lt(0)) return `${code} ${amount}`;
  const fixed = value.toFixed(scale);
  const [majorPart, minorPart = ''] = fixed.split('.');

  if (locale === 'zh-CN') {
    const name = CURRENCY_NAMES_ZH[code];
    if (!name) return `${code} ${fixed}`;
    const majorWords = toChineseInteger(BigInt(majorPart ?? '0'));
    if (scale === 0) return `${name}${majorWords}元整`;
    const minorInt = Number(minorPart.padEnd(scale, '0'));
    if (minorInt === 0) return `${name}${majorWords}元整`;
    if (scale === 2) {
      const jiao = Math.floor(minorInt / 10);
      const fen = minorInt % 10;
      const minorWords = `${jiao > 0 ? `${ZH_DIGITS[jiao]}角` : ''}${
        fen > 0 ? `${ZH_DIGITS[fen]}分` : ''
      }`;
      return `${name}${majorWords}元${minorWords}`;
    }
    return `${name}${majorWords}元${toChineseInteger(BigInt(minorInt))}`;
  }

  const names = CURRENCY_NAMES[code];
  if (!names) return `${code} ${fixed}`;
  const majorValue = BigInt(majorPart ?? '0');
  const majorWords = capitalise(integerToWords(majorValue));
  if (scale === 0) return `${names.major} ${majorWords} Only`;
  const minorInt = Number(minorPart.padEnd(scale, '0'));
  if (minorInt === 0) return `${names.major} ${majorWords} Only`;
  return `${names.major} ${majorWords} and ${capitalise(integerToWords(BigInt(minorInt)))} ${names.minor} Only`;
}
